from itertools import combinations_with_replacement

def count_diamonds(parts):
    n = sum(parts)
    total = 0
    # Sum over all pairs of parts (j, l) for the shared edge
    for j in range(len(parts)):
        for l in range(j + 1, len(parts)):
            # Shared edge connects parts j and l
            # u, v must be in the same part i, where i != j and i != l
            shared_edge_count = parts[j] * parts[l]
            ways_to_choose_uv = 0
            for i in range(len(parts)):
                if i != j and i != l:
                    ways_to_choose_uv += parts[i] * (parts[i] - 1) // 2
            total += shared_edge_count * ways_to_choose_uv
    return total

def optimize_k(n, k):
    # For a fixed k, the parts should be as equal as possible
    base = n // k
    rem = n % k
    parts = [base + 1] * rem + [base] * (k - rem)
    return count_diamonds(parts)

for k in range(2, 121):
    print(f"k={k}, diamonds={optimize_k(120, k)}")
